mapper.select:
SELECT id, name, path, icon, type, sort, status, parent_id, created_at, updated_at
FROM menus
WHERE id = #{id}

mapper.update:
UPDATE menus
SET name = #{name}, path = #{path}, icon = #{icon}, type = #{type},
    sort = #{sort}, status = #{status}, parent_id = #{parentId}, updated_at = #{updatedAt}
WHERE id = #{id}

mapper.select:
SELECT COUNT(*)
FROM menus
WHERE id = #{id}

SELECT COUNT(*)
FROM menus
WHERE parent_id = #{parentId}
